# Test CRC32 with different init/xorout/reflection
def crc32_custom(poly, init, xorout, refin, refout, data):
    # bitwise crc32
    if refin:
        # bit reflected table/impl
        reg = init
        for b in data:
            reg ^= b
            for _ in range(8):
                if reg & 1:
                    reg = (reg >> 1) ^ poly
                else:
                    reg >>= 1
        return (reg ^ xorout) & 0xffffffff
    else:
        reg = init
        for b in data:
            reg ^= (b << 24)
            for _ in range(8):
                if reg & 0x80000000:
                    reg = ((reg << 1) ^ poly) & 0xffffffff
                else:
                    reg = (reg << 1) & 0xffffffff
        return (reg ^ xorout) & 0xffffffff

