# Let us check how amount formatting is formatted:
def format_amount(val_int, is_negative, currency):
    # Determine decimals
    # ISO 4217 standard decimals:
    # 0 decimals:
    ZERO_DEC = {"BIF", "CLP", "DJF", "GNF", "ISK", "JPY", "KMF", "KRW", "PYG", "RWF", "UGX", "UYI", "VND", "VUV", "XAF", "XOF", "XPF"}
    THREE_DEC = {"BHD", "IQD", "JOD", "KWD", "LYD", "OMR", "TND"}
    FOUR_DEC = {"CLF", "UYW"}

    if currency in ZERO_DEC:
        decimals = 0
    elif currency in THREE_DEC:
        decimals = 3
    elif currency in FOUR_DEC:
        decimals = 4
    else:
        decimals = 2

    sign = "-" if is_negative else ""
    if decimals == 0:
        return f"{sign}{val_int}"
    else:
        # e.g. val_int = 4510, decimals = 2 -> 45.10
        # What if val_int < 10**decimals, e.g. 5 -> 0.05
        s = str(val_int).zfill(decimals + 1)
        int_part = s[:-decimals]
        frac_part = s[-decimals:]
        return f"{sign}{int_part}.{frac_part}"

print("Test JPY 439454:", format_amount(439454, False, "JPY"))
